/* Standalone portfolio demonstration. No network requests, credentials or production data. */
(() => {
'use strict';
const $ = (s, r=document) => r.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = cents => new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(cents/100);
const pretty = v => String(v ?? '').replaceAll('_',' ');
const badge = s => `<span class="badge ${esc(s)}">${esc(pretty(s))}</span>`;
const btn = (label, action, id='', primary=false) => `<button type="button" class="btn ${primary?'primary':''} small" data-action="${action}" data-id="${id}">${label}</button>`;
const empty = text => `<div class="empty">${esc(text)}</div>`;
const options = (items,current) => items.map(x => `<option value="${esc(x)}" ${x===current?'selected':''}>${esc(pretty(x))}</option>`).join('');
const clientOptions = id => state.clients.filter(c=>!c.archived).map(c=>`<option value="${c.id}" ${c.id===Number(id)?'selected':''}>${esc(c.name)}</option>`).join('');
const tasks = () => ['Review accepted quote and confirm scope','Confirm contact and communication method','Collect access, content, and assets','Confirm hosting and technical setup','Prepare project plan and milestones','Complete project kickoff'].map(label=>({label,done:false}));
const seed = () => ({version:1, clients:[
 {id:1,name:'Cedar & Co',contact:'Sam Morgan',email:'sam@cedar.example',city:'Guelph, ON',source:'Website inquiry',notes:'Fictional studio exploring a clearer intake process.'},
 {id:2,name:'Aurora Studio',contact:'Alex Rivera',email:'alex@aurora.example',city:'Fergus, ON',source:'Referral',notes:'Fictional creative studio. Prefers a short weekly update.'},
 {id:3,name:'Northwind Workshop',contact:'Jamie Chen',email:'jamie@northwind.example',city:'Mount Forest, ON',source:'Referral',notes:'Fictional workshop website and delivery project.'},
 {id:4,name:'Meadow Community Group',contact:'Taylor Reed',email:'taylor@meadow.example',city:'Elora, ON',source:'Community',notes:'Fictional group organizing event information.'}
 ], inquiries:[
 {id:1,name:'Cedar & Co',contact:'Sam Morgan',email:'sam@cedar.example',problem:'Requests arrive through email and forms. We need one place to track the next step.',status:'new',urgency:'high',next:'Review requirements and prepare a quote',follow:'2026-11-14',draft:''},
 {id:2,name:'Riverbend Books',contact:'Casey Brooks',email:'casey@riverbend.example',problem:'Our website needs clearer navigation and a simple event calendar.',status:'new',urgency:'normal',next:'Clarify content and timeline',follow:'2026-11-16',draft:''},
 {id:3,name:'Willow Arts Club',contact:'Robin Lee',email:'robin@willow.example',problem:'We would like to improve our volunteer sign-up process.',status:'reviewing',urgency:'normal',next:'Review current tools',follow:'2026-11-18',draft:''}
 ], quotes:[
 {id:1,number:'DEMO-Q001',clientId:1,name:'Inquiry workflow setup',overview:'A small intake and tracking workflow for the fictional studio.',scope:'Review current intake; configure request capture; organize a review dashboard; test the workflow; provide a short handover.',items:[{description:'Workflow setup',qty:1,unit:120000}],tax:13,discount:0,deposit:30,status:'draft',follow:'2026-11-17',projectId:null},
 {id:2,number:'DEMO-Q002',clientId:2,name:'Portfolio website refresh',overview:'A clearer showcase of selected work.',scope:'Organize content; build responsive pages; review navigation; test mobile layouts.',items:[{description:'Website refresh',qty:1,unit:85000}],tax:13,discount:0,deposit:25,status:'sent',follow:'2026-11-15',projectId:null},
 {id:3,number:'DEMO-Q003',clientId:3,name:'Workshop website',overview:'A responsive site for fictional workshop information.',scope:'Plan content; build pages; review with the customer; complete handover.',items:[{description:'Website implementation',qty:1,unit:180000}],tax:13,discount:0,deposit:30,status:'accepted',follow:'',projectId:1},
 {id:4,number:'DEMO-Q004',clientId:4,name:'Community event hub',overview:'A central place for event information.',scope:'Organize events; build responsive pages; test and hand over.',items:[{description:'Event hub implementation',qty:1,unit:90000}],tax:13,discount:0,deposit:0,status:'accepted',follow:'',projectId:2}
 ], projects:[
 {id:1,quoteId:3,clientId:3,name:'Workshop website',status:'active',priority:'high',milestone:'Content and first build',waiting:'Customer photos',next:'Review the first page layout',follow:'2026-11-16',approved:false,tasks:tasks().map((t,i)=>({...t,done:i<2}))},
 {id:2,quoteId:4,clientId:4,name:'Community event hub',status:'approved',priority:'normal',milestone:'Billing and handover',waiting:'Final payment',next:'Confirm payment and complete handover',follow:'2026-11-19',approved:true,tasks:tasks().map(t=>({...t,done:true}))}
 ], invoices:[{id:1,number:'DEMO-I001',quoteId:4,projectId:2,clientId:4,total:101700,status:'partial',due:'2026-11-25',payments:[{amount:50000,method:'Demo transfer',date:'2026-11-10',reference:'SAMPLE-01'}]}],
 queue:[{id:1,type:'message',entityId:1,clientId:1,subject:'Requirements review',body:'Hi Sam, thanks for outlining your intake workflow. Could you confirm the fields you need to capture?',status:'awaiting'}],
 leads:[{id:1,name:'Maple Learning Circle',area:'Wellington County',category:'Community organization',score:88,status:'unreviewed',notes:'Fictional opportunity. Review fit before considering outreach.'},{id:2,name:'Harbour Craft Collective',area:'Guelph',category:'Creative group',score:76,status:'shortlisted',notes:'Fictional public lead for evaluating the review workflow.'},{id:3,name:'Pinecrest Makers',area:'Fergus',category:'Workshop',score:69,status:'unreviewed',notes:'Fictional record. No contact lookup or outreach is performed.'}],
 content:[{id:1,title:'A practical guide to tracking requests',channel:'Article',status:'idea',body:'Outline: capture the request, name the next step, set a follow-up, and keep the history together.'},{id:2,title:'What human approval means in an AI workflow',channel:'Portfolio note',status:'draft',body:'Explain how drafting, review, approval, and execution are separated.'}],
 activity:[{id:1,clientId:4,text:'Sample invoice recorded with a partial demo payment.',kind:'Billing',time:'Sample history'},{id:2,clientId:3,text:'Accepted quote converted into a project with six kickoff tasks.',kind:'Project',time:'Sample history'},{id:3,clientId:2,text:'Quote marked as delivered in the sample history.',kind:'Quote',time:'Sample history'}]
});
let state;
try { state=JSON.parse(sessionStorage.getItem('joanna-ops-demo-v1')); if(!state||state.version!==1||!Array.isArray(state.quotes)||!Array.isArray(state.activity)) state=seed(); } catch { state=seed(); }
let view='overview', search='', filter='all', tour=-1, modalSave=null, activeQuote=null, toastTimer;
const dialog=$('#record-dialog');
const nextId = list => Math.max(0,...list.map(r=>r.id))+1;
const client = id => state.clients.find(c=>c.id===Number(id));
const quote = id => state.quotes.find(q=>q.id===Number(id));
const project = id => state.projects.find(p=>p.id===Number(id));
const invoice = id => state.invoices.find(i=>i.id===Number(id));
const totals = q => { const subtotal=q.items.reduce((s,i)=>s+Math.round(i.qty*i.unit),0), discount=Math.round(subtotal*q.discount/100), tax=Math.round((subtotal-discount)*q.tax/100); return {subtotal,discount,tax,total:subtotal-discount+tax,deposit:Math.round((subtotal-discount+tax)*q.deposit/100)}; };
const paid = i => i.payments.reduce((s,p)=>s+p.amount,0);
const balance = i => Math.max(0,i.total-paid(i));
function log(text,clientId=null,kind='Demo action'){state.activity.unshift({id:nextId(state.activity),clientId,text,kind,time:new Date().toLocaleTimeString('en-CA',{hour:'2-digit',minute:'2-digit'})});}
function persist(){try{sessionStorage.setItem('joanna-ops-demo-v1',JSON.stringify(state));}catch{/* Demo remains usable when storage is blocked. */}}
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5500);}
function changed(text){persist();render();if(text)notify(text);}
function go(name){view=name;search='';filter='all';render();}
const sections=[['overview','◫','Overview'],['inquiries','↙','Inquiries'],['clients','◉','Clients'],['quotes','▤','Quotes'],['projects','▦','Projects'],['invoices','＄','Invoices & payments'],['approvals','✓','Approval queue'],['leads','⌕','Local opportunities'],['content','✎','Content'],['archive','□','Archive']];
const tourSteps=[
 ['overview','A connected operations workspace','This demo shows the original system’s core workflows using fictional records. Start with the overview, then follow the sections.'],
 ['inquiries','Capture and qualify a request','Open Cedar & Co, generate a simulated AI reply, or convert the inquiry into a client and draft quote.'],
 ['quotes','Turn a request into a reviewed quote','Edit a draft, change line items, preview totals, and queue delivery for review. Accept a delivered quote to create a project.'],
 ['projects','Track the work and its dependencies','Open a project to change its milestone, mark tasks complete, record approval, and check completion readiness.'],
 ['invoices','Make billing part of delivery','Create an invoice from an accepted quote, record a fictional payment, and watch the balance update. No financial transaction happens.'],
 ['approvals','Keep a person in control','Review queued messages, approve them, and explicitly simulate delivery. There is no email integration in this demo.'],
 ['leads','Review opportunities deliberately','Search fictional opportunities, change their review status, and save notes. Content ideas and archived records have their own sections.'],
 ['overview','Explore freely','All changes stay in this tab. Reset restores the original fictional workspace. The live application, database and real customer information are separate.']
];
function renderTour(){const p=$('#tour-panel');if(tour<0){p.innerHTML='';return;}const s=tourSteps[tour];p.innerHTML=`<section class="tour-panel" aria-label="Guided tour"><div><p class="eyebrow">GUIDED TOUR <span class="tour-step">${tour+1} / ${tourSteps.length}</span></p><h2>${esc(s[1])}</h2><p>${esc(s[2])}</p></div><div class="actions">${tour>0?btn('← Back','tour-prev'):''}${btn(tour===tourSteps.length-1?'Finish tour':'Next →','tour-next')}${btn('Close','tour-close')}</div></section>`;}
function table(headers,rows){return rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty('No matching records. Try another search or filter.');}
function intro(title,text,action=''){return `<div class="intro-row"><div><h2>${title}</h2><p>${text}</p></div>${action}</div>`;}
function toolbar(statuses=[]){return `<div class="toolbar"><label><span class="note">Search records</span><br><input id="search" type="search" placeholder="Search this section…" value="${esc(search)}"></label>${statuses.length?`<label><span class="note">Status</span><br><select id="status-filter"><option value="all">All statuses</option>${options(statuses,filter)}</select></label>`:''}</div>`;}
function matches(r,text){return !r.archived&&(!search||String(text).toLowerCase().includes(search.toLowerCase()))&&(filter==='all'||r.status===filter);}
function activities(list){return list.length?list.slice(0,8).map(a=>`<div class="activity"><span class="activity-dot"></span><div><p>${esc(a.text)}</p><small>${esc(a.kind)} · ${esc(a.time)}</small></div></div>`).join(''):empty('Activity appears here as you explore.');}
function overview(){const outstanding=state.invoices.reduce((s,i)=>s+balance(i),0), active=state.projects.filter(p=>!p.archived&&p.status!=='completed'), draft=state.quotes.filter(q=>!q.archived&&q.status==='draft');return intro('A clear view of what needs attention','A fictional workspace, built around the journey from first request to handover.',btn('Try the full workflow','workflow-start','',true))+`<div class="stats"><div class="stat"><small>Open inquiries</small><strong>${state.inquiries.filter(i=>!i.archived&&['new','reviewing'].includes(i.status)).length}</strong><span>Capture → review → next step</span></div><div class="stat"><small>Active projects</small><strong>${active.length}</strong><span>Milestones and kickoff checklists</span></div><div class="stat"><small>Draft quotes</small><strong>${draft.length}</strong><span>Review before simulated delivery</span></div><div class="stat"><small>Outstanding · CAD</small><strong>${money(outstanding)}</strong><span>Fictional invoice balances</span></div></div><div class="grid-two"><section class="panel"><div class="panel-heading"><h3>Project delivery</h3>${btn('All projects →','nav-projects')}</div>${active.map(p=>{const n=p.tasks.filter(t=>t.done).length;return `<div class="mini-row"><div class="mini-top"><button class="link-button" data-action="project-open" data-id="${p.id}">${esc(p.name)}</button>${badge(p.status)}</div><p>${esc(client(p.clientId)?.name)} · ${esc(p.milestone)}</p><progress class="progress" max="${p.tasks.length}" value="${n}" aria-label="${esc(p.name)} completed tasks"></progress><p>${n} of ${p.tasks.length} kickoff tasks complete</p></div>`;}).join('')}</section><section class="panel"><div class="panel-heading"><h3>Recent activity</h3><span class="note">Sample + this session</span></div>${activities(state.activity)}</section></div><section class="panel"><div class="panel-heading"><div><h3>From first request to completed work</h3><p>Try the sequence using the seeded records or create your own fictional example.</p></div></div><div class="workflow"><div><small>01 / CAPTURE</small>Review inquiry</div><div><small>02 / SCOPE</small>Prepare quote</div><div><small>03 / DELIVER</small>Create project</div><div><small>04 / BILL</small>Invoice and payment</div><div><small>05 / CLOSE</small>Readiness and handover</div></div><div class="callout"><strong>Where human approval fits</strong>AI drafts and outgoing messages enter a review queue. Approval and simulated delivery are separate, deliberate actions.</div><details><summary>About the original build and this demonstration</summary><p class="muted">Joanna developed and integrated the original dashboard with AI-assisted tools, configuring application services, PostgreSQL data, workflow rules, validation, and approval controls. This browser-only demonstration recreates its documented workflows with fictional records; AI, email delivery and payments are simulated. It does not connect to the original application.</p></details></section>`;}
function inquiriesView(){return intro('Every request has a next step','Review the problem, draft a reply, and turn a qualified request into a client record.',btn('+ Add inquiry','inquiry-new','',true))+toolbar(['new','reviewing','converted','closed'])+table(['Request','Priority','Status','Follow-up','Action'],state.inquiries.filter(i=>matches(i,i.name+' '+i.problem)).map(i=>`<tr><td><button class="link-button" data-action="inquiry-open" data-id="${i.id}">${esc(i.name)}</button><small>${esc(i.problem)}</small></td><td>${badge(i.urgency)}</td><td>${badge(i.status)}</td><td>${esc(i.follow||'Not scheduled')}<small>${esc(i.next)}</small></td><td>${btn('Open','inquiry-open',i.id)}</td></tr>`));}
function clientsView(){return intro('Client context in one place','Contacts, notes, related work, and a communication timeline.',btn('+ Add client','client-new','',true))+toolbar()+table(['Organization','Primary contact','Location','Related work','Action'],state.clients.filter(c=>matches(c,c.name+' '+c.contact+' '+c.email)).map(c=>`<tr><td><button class="link-button" data-action="client-open" data-id="${c.id}">${esc(c.name)}</button><small>${esc(c.source)}</small></td><td>${esc(c.contact)}<small>${esc(c.email)}</small></td><td>${esc(c.city)}</td><td>${state.projects.filter(p=>p.clientId===c.id&&!p.archived).length} projects · ${state.quotes.filter(q=>q.clientId===c.id&&!q.archived).length} quotes</td><td>${btn('View / edit','client-open',c.id)}</td></tr>`));}
function quotesView(){return intro('Scope, pricing, and decisions stay connected','Draft → review → simulate delivery → record the response → create a project.',btn('+ New quote','quote-new','',true))+toolbar(['draft','sent','accepted','declined','expired','superseded'])+table(['Quote','Client','Status','Total · CAD','Next step'],state.quotes.filter(q=>matches(q,q.name+' '+q.number+' '+client(q.clientId)?.name)).map(q=>`<tr><td><button class="link-button" data-action="quote-open" data-id="${q.id}">${esc(q.number)}</button><small>${esc(q.name)}</small></td><td>${esc(client(q.clientId)?.name)}</td><td>${badge(q.status)}${q.revisionOf?'<small>Revision of '+esc(quote(q.revisionOf)?.number)+'</small>':''}</td><td>${money(totals(q).total)}</td><td><div class="actions">${btn('Open','quote-open',q.id)}${q.status==='accepted'&&!q.projectId?btn('Create project','quote-project',q.id,true):''}</div></td></tr>`));}
function projectsView(){return intro('Delivery has a clear path','Track tasks, milestones, dependencies, approval, billing, and completion readiness.')+toolbar(['planned','active','waiting_on_customer','customer_review','approved','handoff','completed'])+`<div class="cards">${state.projects.filter(p=>matches(p,p.name+' '+client(p.clientId)?.name)).map(p=>`<article class="record-card"><div class="mini-top">${badge(p.status)}<span class="note">${esc(p.priority)} priority</span></div><h3>${esc(p.name)}</h3><p>${esc(client(p.clientId)?.name)} · ${esc(p.milestone)}</p><progress class="progress" max="${p.tasks.length}" value="${p.tasks.filter(t=>t.done).length}" aria-label="${esc(p.name)} completed tasks"></progress><p>${p.tasks.filter(t=>t.done).length}/${p.tasks.length} kickoff tasks · ${p.approved?'Customer approved':'Approval pending'}</p><div class="actions">${btn('Open project','project-open',p.id,true)}${p.status==='completed'?btn('Archive','project-archive',p.id):''}</div></article>`).join('')||empty('No matching projects.')}</div>`;}
function invoicesView(){return intro('Invoices and payments linked to the work','Invoices require accepted quotes. Demo payments update balances; no money moves.',btn('+ Create from accepted quote','invoice-new','',true))+toolbar(['draft','sent','partial','paid'])+table(['Invoice','Client','Status','Total · CAD','Balance · CAD','Action'],state.invoices.filter(i=>matches(i,i.number+' '+client(i.clientId)?.name)).map(i=>`<tr><td><button class="link-button" data-action="invoice-open" data-id="${i.id}">${esc(i.number)}</button><small>Due ${esc(i.due)}</small></td><td>${esc(client(i.clientId)?.name)}</td><td>${badge(i.status)}</td><td>${money(i.total)}</td><td><strong>${money(balance(i))}</strong></td><td>${btn('Open / payment','invoice-open',i.id)}</td></tr>`));}
function approvalsView(){return intro('A deliberate pause before anything goes out','Review the draft, approve it, then explicitly simulate delivery. No email is sent.')+`<div class="callout"><strong>Human control is part of the workflow</strong>Drafting, approval, and delivery are distinct states. The live system uses an execution queue; this demo changes fictional state only.</div>`+toolbar(['awaiting','approved','delivered','rejected'])+table(['Draft message','Recipient','State','Action'],state.queue.filter(q=>matches(q,q.subject+' '+client(q.clientId)?.name)).map(q=>`<tr><td><button class="link-button" data-action="queue-open" data-id="${q.id}">${esc(q.subject)}</button><small>${esc(q.type)} · Simulated delivery only</small></td><td>${esc(client(q.clientId)?.contact)}<small>${esc(client(q.clientId)?.email)}</small></td><td>${badge(q.status)}</td><td><div class="actions">${btn('Review','queue-open',q.id)}${q.status==='awaiting'?btn('Approve','queue-approve',q.id):''}${q.status==='approved'?btn('Simulate delivery','queue-deliver',q.id,true):''}</div></td></tr>`));}
function leadsView(){return intro('Research becomes a reviewable opportunity','Fictional scout results demonstrate shortlisting and notes. No real businesses are contacted.')+toolbar(['unreviewed','shortlisted','dismissed'])+table(['Opportunity','Area','Fit score','Review status','Action'],state.leads.filter(l=>matches(l,l.name+' '+l.category+' '+l.area)).map(l=>`<tr><td><strong>${esc(l.name)}</strong><small>${esc(l.category)}</small></td><td>${esc(l.area)}</td><td>${l.score} / 100</td><td>${badge(l.status)}</td><td>${btn('Review','lead-open',l.id)}</td></tr>`));}
function contentView(){return intro('A place for ideas before publication','Create, edit, and organize content drafts. Saving does not publish anything.',btn('+ Add idea','content-new','',true))+toolbar(['idea','draft','ready'])+`<div class="cards">${state.content.filter(c=>matches(c,c.title+' '+c.body)).map(c=>`<article class="record-card"><div class="mini-top">${badge(c.status)}<span class="note">${esc(c.channel)}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.body.slice(0,180))}</p><div class="actions">${btn('Edit draft','content-open',c.id,true)}${btn('Archive','content-archive',c.id)}</div></article>`).join('')||empty('No matching content ideas.')}</div>`;}
function archiveView(){const rows=[];for(const [key,label] of [['inquiries','Inquiry'],['quotes','Quote'],['projects','Project'],['content','Content']])for(const r of state[key].filter(x=>x.archived))rows.push(`<tr><td>${label}</td><td>${esc(r.title||r.name)}${r.number?'<small>'+esc(r.number)+'</small>':''}</td><td>${badge(r.status)}</td><td>${btn('Restore','restore-'+key,r.id)}</td></tr>`);return intro('History stays recoverable','Archived records leave the active lists. Restore brings them back without losing their history.')+table(['Type','Record','Status','Action'],rows);}
const views={overview,inquiries:inquiriesView,clients:clientsView,quotes:quotesView,projects:projectsView,invoices:invoicesView,approvals:approvalsView,leads:leadsView,content:contentView,archive:archiveView};
function render(){const count=state.queue.filter(q=>q.status==='awaiting').length;$('#navigation').innerHTML=sections.map(([key,icon,label])=>`<button data-view="${key}" ${view===key?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}${key==='approvals'&&count?`<span class="nav-count">${count}</span>`:''}</button>`).join('');$('#page-title').textContent=sections.find(s=>s[0]===view)[2];renderTour();$('#view').innerHTML=views[view]();}
function field(label,name,value='',type='text',full=false,required=false){return `<label class="${full?'full':''}">${label}<input name="${name}" type="${type}" ${type==='number'?'step="any" min="0"':''} value="${esc(value)}" ${required?'required':''} maxlength="${type==='text'?500:200}"></label>`;}
function area(label,name,value=''){return `<label class="full">${label}<textarea name="${name}" maxlength="5000">${esc(value)}</textarea></label>`;}
function select(label,name,items,value){return `<label>${label}<select name="${name}">${options(items,value)}</select></label>`;}
function openModal(title,body,save=null,saveLabel='Save changes'){modalSave=save;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#form-error').textContent='';$('#dialog-save').hidden=!save;$('#dialog-save').textContent=saveLabel;$('#record-form .dialog-actions .btn').textContent=save?'Cancel':'Close';if(!dialog.open)dialog.showModal();}
function formValues(){return Object.fromEntries(new FormData($('#record-form')));}
function closeModal(){dialog.close();modalSave=null;activeQuote=null;}
function inquiryModal(id){const i=state.inquiries.find(x=>x.id===Number(id));const base=i||{name:'',contact:'',email:'',problem:'',status:'new',urgency:'normal',next:'Review the request',follow:'',draft:''};openModal(i?'Review inquiry':'Add a fictional inquiry',`<div class="form-grid">${field('Organization','name',base.name,'text',false,true)}${field('Contact','contact',base.contact)}${field('Email (fictional)','email',base.email,'email')}${select('Urgency','urgency',['low','normal','high','urgent'],base.urgency)}${select('Status','status',['new','reviewing','converted','closed'],base.status)}${field('Follow-up date','follow',base.follow,'date')}${area('What needs to be solved?','problem',base.problem)}${field('Next action','next',base.next,'text',true)}</div>${i?`<div class="detail-section"><h3>Reply draft</h3><p class="note">AI is simulated here using a local template.</p><textarea id="reply-draft" aria-label="Editable reply draft">${esc(i.draft)}</textarea><div class="actions">${btn('Generate simulated AI draft','inquiry-ai',i.id)}${btn('Queue draft for approval','inquiry-queue',i.id)}</div></div><div class="actions">${i.status!=='converted'?btn('Convert to client + draft quote','inquiry-convert',i.id,true):''}${['new','reviewing','closed'].includes(i.status)?btn('Archive inquiry','inquiry-archive',i.id):''}</div>`:''}`,values=>{if(!values.name.trim())throw Error('Enter an organization name.');if(i)Object.assign(i,values);else state.inquiries.push({...values,id:nextId(state.inquiries),draft:''});if(i)i.draft=$('#reply-draft').value;log(i?'Inquiry updated.':'New fictional inquiry added.');closeModal();changed('Inquiry saved in this demo.');});}
function clientModal(id){const c=client(id),base=c||{name:'',contact:'',email:'',city:'',source:'Manual entry',notes:''};openModal(c?'Client record · '+c.name:'Add a fictional client',`<div class="form-grid">${field('Organization','name',base.name,'text',false,true)}${field('Primary contact','contact',base.contact)}${field('Email (fictional)','email',base.email,'email')}${field('Location','city',base.city)}${field('Source','source',base.source,'text',true)}${area('Notes','notes',base.notes)}</div>${c?`<section class="detail-section"><h3>Related work</h3><p>${state.quotes.filter(q=>q.clientId===c.id&&!q.archived).map(q=>esc(q.number)+' · '+esc(q.name)).join('<br>')||'No quotes yet.'}</p><div class="actions">${btn('Create a quote','client-quote',c.id)}</div></section><section class="detail-section"><h3>Customer activity</h3>${activities(state.activity.filter(a=>a.clientId===c.id))}<div class="actions">${btn('Log a call / meeting / note','client-log',c.id)}</div></section>`:''}`,v=>{if(!v.name.trim())throw Error('Enter an organization name.');if(state.clients.some(x=>x.id!==c?.id&&(x.name.toLowerCase()===v.name.trim().toLowerCase()||(v.email&&x.email.toLowerCase()===v.email.toLowerCase()))))throw Error('A client with this name or email already exists.');if(c)Object.assign(c,v);else state.clients.push({...v,id:nextId(state.clients)});log(c?'Client details updated.':'Fictional client added.',c?.id);closeModal();changed('Client saved.');});}
function readQuoteEditor(){const v=formValues();const items=[...document.querySelectorAll('.quote-line')].map(row=>({description:$('[data-item="description"]',row).value,qty:Number($('[data-item="qty"]',row).value),unit:Math.round(Number($('[data-item="unit"]',row).value)*100)}));return {...v,clientId:Number(v.clientId),tax:Number(v.tax),discount:Number(v.discount),deposit:Number(v.deposit),items};}
function itemMarkup(i,n){return `<div class="quote-line"><label>Item description<input data-item="description" value="${esc(i.description)}" required maxlength="200"></label><label>Qty<input data-item="qty" type="number" min="1" max="999" step="1" value="${i.qty}" required></label><label>Price · CAD<input data-item="unit" type="number" min="0" max="1000000" step="0.01" value="${(i.unit/100).toFixed(2)}" required></label><button type="button" class="icon-button" data-action="quote-item-remove" data-id="${n}" aria-label="Remove item ${n+1}">×</button></div>`;}
function quoteModal(id,initial=null){const q=quote(id),base=q||initial||{clientId:state.clients[0].id,name:'New project',overview:'',scope:'',items:[{description:'Implementation',qty:1,unit:100000}],tax:13,discount:0,deposit:30,follow:'',status:'draft'};activeQuote=q?.id||null;const editable=!q||q.status==='draft';if(!editable){openModal(q.number+' · '+q.name,quotePreview(q)+`<div class="actions no-print">${btn('Print / save preview','print-quote',q.id)}${q.status==='sent'?btn('Record accepted','quote-accept',q.id,true)+btn('Record declined','quote-decline',q.id):''}${q.status==='accepted'&&!q.projectId?btn('Create project + kickoff tasks','quote-project',q.id,true):''}${['sent','declined','expired'].includes(q.status)?btn('Create revision','quote-revise',q.id):''}${q.projectId?btn('Open linked project','project-open',q.projectId):''}${['declined','expired','superseded'].includes(q.status)&&!q.projectId?btn('Archive quote','quote-archive',q.id):''}</div>`);return;}
openModal(q?q.number+' · Edit draft':'Create a quote',`<div class="form-grid"><label>Client<select name="clientId">${clientOptions(base.clientId)}</select></label>${field('Project name','name',base.name,'text',false,true)}${area('Overview','overview',base.overview)}${area('Included scope','scope',base.scope)}${field('Tax (%)','tax',base.tax,'number')}${field('Discount (%)','discount',base.discount,'number')}${field('Deposit (%)','deposit',base.deposit,'number')}${field('Follow-up date','follow',base.follow,'date')}</div><section class="detail-section"><h3>Pricing items</h3><div class="quote-items" id="quote-items">${base.items.map(itemMarkup).join('')}</div><div class="actions">${btn('+ Add item','quote-item-add')}</div><div id="quote-live-totals">${totalMarkup(base)}</div></section>${q?`<div class="actions">${btn('Preview saved quote','quote-preview',q.id)}${btn('Queue saved quote for approval','quote-queue',q.id,true)}${btn('Archive draft','quote-archive',q.id)}</div><p class="note">Save edits before previewing or queueing the quote.</p>`:''}`,v=>{const d=readQuoteEditor();if(!d.name.trim()||!d.items.length)throw Error('Add a project name and at least one pricing item.');if([d.tax,d.discount,d.deposit].some(n=>!Number.isFinite(n)||n<0||n>100))throw Error('Tax, discount and deposit must be between 0 and 100.');if(d.items.some(i=>!i.description.trim()||!Number.isFinite(i.qty)||i.qty<1||!Number.isInteger(i.qty)||!Number.isFinite(i.unit)||i.unit<0))throw Error('Each item needs a description, a whole quantity and a valid non-negative price.');if(q)Object.assign(q,d);else{const n=nextId(state.quotes);state.quotes.push({...d,id:n,number:'DEMO-Q'+String(n).padStart(3,'0'),status:'draft',projectId:null});}log(q?'Quote draft updated.':'Quote draft created.',d.clientId,'Quote');closeModal();go('quotes');changed('Quote saved. Open it to preview or queue delivery.');});}
function totalMarkup(q){const t=totals(q);return `<div class="totals"><div class="total-row"><span>Subtotal</span><span>${money(t.subtotal)}</span></div><div class="total-row"><span>Discount (${q.discount}%)</span><span>−${money(t.discount)}</span></div><div class="total-row"><span>Tax (${q.tax}%)</span><span>${money(t.tax)}</span></div><div class="total-row grand"><span>Total · CAD</span><span>${money(t.total)}</span></div><div class="total-row"><span>Deposit (${q.deposit}%)</span><span>${money(t.deposit)}</span></div></div>`;}
function quotePreview(q){return `<div class="callout"><strong>Fictional quote preview · ${esc(q.number)}</strong>For demonstration only. This is not a commercial offer.</div><div class="detail-grid"><div><small>Prepared for</small>${esc(client(q.clientId)?.name)}<br>${esc(client(q.clientId)?.contact)}</div><div><small>Status / follow-up</small>${badge(q.status)}<br>${esc(q.follow||'No follow-up scheduled')}</div></div><section class="detail-section"><h3>${esc(q.name)}</h3><p>${esc(q.overview)}</p><h3>Included scope</h3><p>${esc(q.scope).replaceAll('\n','<br>')}</p></section>${table(['Description','Quantity','Unit · CAD','Line total · CAD'],q.items.map(i=>`<tr><td>${esc(i.description)}</td><td>${i.qty}</td><td>${money(i.unit)}</td><td>${money(i.qty*i.unit)}</td></tr>`))}${totalMarkup(q)}`;}
function createProject(q){if(q.status!=='accepted')throw Error('A quote must be accepted before project creation.');if(q.projectId){projectModal(q.projectId);notify('This quote already has a project.');return;}const n=nextId(state.projects);state.projects.push({id:n,quoteId:q.id,clientId:q.clientId,name:q.name,status:'planned',priority:'normal',milestone:'Kickoff',waiting:'',next:'Review accepted scope and complete kickoff tasks',follow:'',approved:false,tasks:tasks()});q.projectId=n;log('Accepted quote created a project with six kickoff tasks.',q.clientId,'Project');persist();go('projects');projectModal(n);notify('Project and kickoff tasks created.');}
function readiness(p){const inv=state.invoices.find(i=>i.projectId===p.id), checks=[['Kickoff checklist complete',p.tasks.every(t=>t.done)],['Customer approval recorded',p.approved],['Invoice created',!!inv],['Invoice fully paid',!!inv&&balance(inv)===0],['Handover recorded',p.status==='handoff'||p.status==='completed']];return checks;}
function projectModal(id){const p=project(id),q=quote(p.quoteId),inv=state.invoices.find(i=>i.projectId===p.id);openModal(p.name,`<div class="detail-grid"><div><small>Client / accepted quote</small>${esc(client(p.clientId)?.name)}<br>${esc(q.number)}</div><div><small>Billing</small>${inv?esc(inv.number)+' · '+money(balance(inv))+' remaining':'No invoice created'}</div></div><div class="form-grid">${select('Delivery status','status',['planned','active','waiting_on_customer','customer_review','approved','handoff','completed'],p.status)}${select('Priority','priority',['low','normal','high'],p.priority)}${field('Current milestone','milestone',p.milestone)}${field('Waiting on','waiting',p.waiting)}${field('Next step','next',p.next,'text',true)}${field('Follow-up date','follow',p.follow,'date')}</div><section class="detail-section"><h3>Kickoff checklist</h3>${p.tasks.map((t,n)=>`<label class="check-row"><input type="checkbox" name="task-${n}" ${t.done?'checked':''}>${esc(t.label)}</label>`).join('')}<label class="check-row"><input type="checkbox" name="approved" ${p.approved?'checked':''}>Customer approval recorded</label></section><section class="detail-section"><h3>Completion readiness · saved state</h3><ul class="readiness">${readiness(p).map(([label,ok])=>`<li class="${ok?'pass':'pending'}">${ok?'✓':'○'} ${label}</li>`).join('')}</ul><p class="note">Save changes to refresh these checks. Completion requires the checklist, customer approval, payment, and a recorded handover.</p></section><div class="actions">${inv?btn('Open invoice','invoice-open',inv.id):btn('Create invoice from accepted quote','project-invoice',p.id)}${btn('Log project update','project-log',p.id)}</div><section class="detail-section"><h3>Communication timeline</h3>${activities(state.activity.filter(a=>a.clientId===p.clientId))}</section>`,v=>{const taskState=p.tasks.map((t,n)=>({...t,done:v['task-'+n]==='on'})), approved=v.approved==='on';if(v.status==='completed'&&!(taskState.every(t=>t.done)&&approved&&inv&&balance(inv)===0&&['handoff','completed'].includes(p.status)))throw Error('Complete the checklist, record approval, pay the invoice, then save Handoff before completing the project.');Object.assign(p,{status:v.status,priority:v.priority,milestone:v.milestone,waiting:v.waiting,next:v.next,follow:v.follow,approved,tasks:taskState});log('Project delivery details and readiness updated.',p.clientId,'Project');closeModal();changed('Project saved.');});}
function createInvoice(q){if(q.status!=='accepted')throw Error('Only an accepted quote can be invoiced.');if(!q.projectId)throw Error('Create the delivery project first so the invoice stays linked to the work.');const existing=state.invoices.find(i=>i.quoteId===q.id);if(existing){invoiceModal(existing.id);notify('Duplicate prevented: this quote already has an invoice.');return;}const t=totals(q);if(!q.items.length||t.total<=0)throw Error('The accepted quote needs selected items and a positive total.');const n=nextId(state.invoices);state.invoices.push({id:n,number:'DEMO-I'+String(n).padStart(3,'0'),quoteId:q.id,projectId:q.projectId,clientId:q.clientId,total:t.total,status:'draft',due:'2026-12-01',payments:[]});log('Invoice created from the accepted quote.',q.clientId,'Billing');persist();go('invoices');invoiceModal(n);notify('Linked invoice created.');}
function invoiceModal(id){const i=invoice(id);openModal(i.number+' · Invoice and payments',`<div class="callout"><strong>Fictional billing record</strong>No payment is collected or transferred. Amounts only update this demo.</div><div class="detail-grid"><div><small>Client / quote</small>${esc(client(i.clientId)?.name)}<br>${esc(quote(i.quoteId)?.number)}</div><div><small>Status / due date</small>${badge(i.status)}<br>${esc(i.due)}</div></div><div class="totals"><div class="total-row"><span>Invoice total</span><span>${money(i.total)}</span></div><div class="total-row"><span>Recorded payments</span><span>${money(paid(i))}</span></div><div class="total-row grand"><span>Balance · CAD</span><span>${money(balance(i))}</span></div></div><section class="detail-section"><h3>Demo payment history</h3>${i.payments.length?table(['Date','Method','Reference','Amount · CAD'],i.payments.map(p=>`<tr><td>${esc(p.date)}</td><td>${esc(p.method)}</td><td>${esc(p.reference)}</td><td>${money(p.amount)}</td></tr>`)):empty('No demo payments recorded.')}</section><div class="actions">${balance(i)>0?btn('Record a demo payment','invoice-payment',i.id,true):''}${i.status==='draft'?btn('Queue invoice for approval','invoice-queue',i.id):''}${btn('Open project','project-open',i.projectId)}</div>`);}
function paymentModal(id){const i=invoice(id);openModal('Record a fictional payment',`<div class="callout">This changes the demo balance only. No money moves.</div><div class="form-grid">${field('Amount · CAD','amount',(balance(i)/100).toFixed(2),'number',false,true)}${select('Method','method',['Demo transfer','Demo card','Demo cash'],'Demo transfer')}${field('Date','date','2026-11-12','date',false,true)}${field('Reference','reference','SAMPLE-PAYMENT')}</div>`,v=>{const amount=Math.round(Number(v.amount)*100);if(!Number.isFinite(amount)||amount<=0||amount>balance(i))throw Error('Enter a positive payment no greater than the remaining '+money(balance(i))+'.');i.payments.push({amount,method:v.method,date:v.date,reference:v.reference});i.status=balance(i)===0?'paid':'partial';log('Fictional payment of '+money(amount)+' recorded.',i.clientId,'Billing');closeModal();changed('Payment recorded in this demo.');invoiceModal(i.id);},'Record demo payment');}
function queueMessage(type,entityId,clientId,subject,body){if(state.queue.some(x=>x.type===type&&x.entityId===entityId&&['awaiting','approved','delivered'].includes(x.status)))throw Error('Duplicate prevented: this item is already queued or delivered.');state.queue.push({id:nextId(state.queue),type,entityId,clientId,subject,body,status:'awaiting'});log('Draft added to the approval queue. No message sent.',clientId,'Approval');closeModal();go('approvals');changed('Draft queued. Review it, approve it, then simulate delivery.');}
function queueModal(id){const q=state.queue.find(x=>x.id===Number(id));openModal('Review draft · '+q.subject,`<div class="detail-grid"><div><small>Fictional recipient</small>${esc(client(q.clientId)?.contact)}<br>${esc(client(q.clientId)?.email)}</div><div><small>Queue state</small>${badge(q.status)}<br>Demo only · No email service</div></div><div class="form-grid">${field('Subject','subject',q.subject,'text',true,true)}${area('Message','body',q.body)}</div><div class="actions">${q.status==='awaiting'?btn('Approve saved draft','queue-approve',q.id,true)+btn('Reject draft','queue-reject',q.id):''}${q.status==='approved'?btn('Simulate delivery','queue-deliver',q.id,true):''}</div><p class="note">Save edits before approving. Editing an approved draft returns it to review.</p>`,['delivered','rejected'].includes(q.status)?null:v=>{q.subject=v.subject;q.body=v.body;q.status='awaiting';closeModal();changed('Draft saved and awaiting review.');});}
function leadModal(id){const l=state.leads.find(x=>x.id===Number(id));openModal('Review opportunity · '+l.name,`<div class="detail-grid"><div><small>Area / type</small>${esc(l.area)}<br>${esc(l.category)}</div><div><small>Sample fit score</small>${l.score} / 100</div></div><div class="form-grid">${select('Review status','status',['unreviewed','shortlisted','dismissed'],l.status)}${area('Review notes','notes',l.notes)}</div>`,v=>{Object.assign(l,v);log('Fictional opportunity review saved.',null,'Research');closeModal();changed('Review saved. No outreach performed.');});}
function contentModal(id){const c=state.content.find(x=>x.id===Number(id)),b=c||{title:'',channel:'Article',status:'idea',body:''};openModal(c?'Edit content draft':'Add a content idea',`<div class="form-grid">${field('Title','title',b.title,'text',true,true)}${select('Format','channel',['Article','Portfolio note','Social post'],b.channel)}${select('Status','status',['idea','draft','ready'],b.status)}${area('Draft / notes','body',b.body)}</div>`,v=>{if(c)Object.assign(c,v);else state.content.push({...v,id:nextId(state.content)});log('Content draft saved locally.',null,'Content');closeModal();changed('Idea saved. Nothing published.');});}
function logModal(id,isProject=false){const p=isProject?project(id):null,c=client(p?p.clientId:id);openModal('Log activity · '+c.name,`<div class="form-grid">${select('Activity type','kind',['Call','Meeting','Email note','Decision','Project update'],'Call')}${area('Summary','text','')}</div>`,v=>{if(!v.text.trim())throw Error('Enter a brief activity summary.');log(v.text,c.id,v.kind);closeModal();changed('Activity added to the timeline.');});}
function resetModal(){openModal('Reset the demo workspace?',`<p>Your changes in this tab will be replaced with the original fictional records.</p>`,()=>{state=seed();tour=-1;closeModal();go('overview');changed('Demo restored to its starting state.');},'Reset fictional records');}
function archive(type,id){const r=state[type].find(x=>x.id===Number(id));if(type==='quotes'&&(!['draft','declined','expired','superseded'].includes(r.status)||r.projectId||state.invoices.some(i=>i.quoteId===r.id)))throw Error('This quote is protected because of its status or linked delivery records.');if(type==='projects'&&r.status!=='completed')throw Error('Complete the delivery checks before archiving a project.');r.archived=true;log('Record archived; history preserved.',r.clientId||null,'Archive');closeModal();changed('Record archived. Restore it from Archive.');}
function act(action,id){switch(action){
case 'close-dialog':closeModal();break;
case 'nav-projects':go('projects');break;
case 'tour-prev':tour=Math.max(0,tour-1);go(tourSteps[tour][0]);break;
case 'tour-next':tour++;if(tour===tourSteps.length){tour=-1;render();notify('Tour complete. Explore freely or reset the demo.');}else go(tourSteps[tour][0]);break;
case 'tour-close':tour=-1;render();break;
case 'workflow-start':tour=1;go('inquiries');inquiryModal(1);break;
case 'inquiry-new':inquiryModal();break;
case 'inquiry-open':inquiryModal(id);break;
case 'inquiry-ai':{const i=state.inquiries.find(x=>x.id===Number(id));$('#reply-draft').value=`Hi ${i.contact.split(' ')[0]}, thanks for explaining the request. I understand the main issue is: ${i.problem} I would first confirm the current process, the information you need to capture, and who reviews each request. Could you share a fictional example of a typical request?`;notify('Simulated AI draft created locally. Review and edit it before queueing.');break;}
case 'inquiry-queue':{const i=state.inquiries.find(x=>x.id===Number(id));i.draft=$('#reply-draft').value;if(!i.draft.trim())throw Error('Generate or write a reply draft first.');const c=state.clients.find(c=>c.name.toLowerCase()===i.name.toLowerCase());if(!c)throw Error('Convert the inquiry to a client before queueing its reply.');queueMessage('message',i.id,c.id,'Re: '+i.name+' inquiry',i.draft);break;}
case 'inquiry-convert':{const i=state.inquiries.find(x=>x.id===Number(id));if(i.status==='converted')throw Error('This inquiry has already been converted.');let c=state.clients.find(c=>c.name.toLowerCase()===i.name.toLowerCase()||(i.email&&c.email.toLowerCase()===i.email.toLowerCase()));if(!c){c={id:nextId(state.clients),name:i.name,contact:i.contact,email:i.email,city:'',source:'Demo inquiry',notes:i.problem};state.clients.push(c);}i.status='converted';log('Inquiry converted; client context reused or created.',c.id,'Intake');persist();closeModal();go('quotes');quoteModal(null,{clientId:c.id,name:'Request workflow project',overview:i.problem,scope:'Confirm requirements; configure the agreed workflow; test; review; hand over.',items:[{description:'Implementation package',qty:1,unit:100000}],tax:13,discount:0,deposit:30,follow:'2026-11-17',status:'draft'});notify('Client ready. Save this draft quote to continue.');break;}
case 'inquiry-archive':archive('inquiries',id);break;
case 'client-new':clientModal();break;
case 'client-open':clientModal(id);break;
case 'client-quote':{const c=client(id);closeModal();quoteModal(null,{clientId:c.id,name:'New project',overview:'',scope:'',items:[{description:'Implementation',qty:1,unit:100000}],tax:13,discount:0,deposit:30,follow:'',status:'draft'});break;}
case 'client-log':logModal(id);break;
case 'quote-new':quoteModal();break;
case 'quote-open':quoteModal(id);break;
case 'quote-preview':{const q=quote(id);openModal(q.number+' · Saved preview',quotePreview(q)+`<div class="actions no-print">${btn('Print / save preview','print-quote',q.id)}${btn('Return to editor','quote-open',q.id)}</div>`);break;}
case 'print-quote':window.print();break;
case 'quote-item-add':{const q=readQuoteEditor();q.items.push({description:'Additional item',qty:1,unit:0});$('#quote-items').innerHTML=q.items.map(itemMarkup).join('');$('#quote-live-totals').innerHTML=totalMarkup(q);break;}
case 'quote-item-remove':{const q=readQuoteEditor();if(q.items.length===1)throw Error('Keep at least one pricing item.');q.items.splice(Number(id),1);$('#quote-items').innerHTML=q.items.map(itemMarkup).join('');$('#quote-live-totals').innerHTML=totalMarkup(q);break;}
case 'quote-queue':{const q=quote(id);if(q.status!=='draft')throw Error('Only draft quotes can enter this delivery queue.');if(totals(q).total<=0)throw Error('Add a positive quote amount first.');queueMessage('quote',q.id,q.clientId,'Quote '+q.number+' · '+q.name,'Please review the fictional scope and pricing for '+q.name+'. Total: '+money(totals(q).total)+'. This is a demo message.');break;}
case 'quote-accept':{const q=quote(id);if(q.status!=='sent')throw Error('Record simulated delivery before acceptance.');q.status='accepted';q.follow='';log('Customer acceptance recorded manually.',q.clientId,'Quote');closeModal();changed('Quote accepted. Create a project to continue.');quoteModal(id);break;}
case 'quote-decline':{const q=quote(id);q.status='declined';q.follow='';log('Quote declined in the demo.',q.clientId,'Quote');closeModal();changed('Quote response recorded.');break;}
case 'quote-project':createProject(quote(id));break;
case 'quote-revise':{const q=quote(id);if(!['sent','declined','expired'].includes(q.status))throw Error('This quote cannot be revised in its current state.');const n=nextId(state.quotes),root=q.number.replace(/-R\d+$/,''),rev=state.quotes.filter(x=>x.number.startsWith(root+'-R')).length+1;state.quotes.push({...JSON.parse(JSON.stringify(q)),id:n,number:root+'-R'+rev,revisionOf:q.id,status:'draft',projectId:null,follow:'2026-11-17'});q.status='superseded';log('Quote revised; earlier version retained as superseded.',q.clientId,'Quote');closeModal();changed('Revision created. Earlier quote retained in history.');quoteModal(n);break;}
case 'quote-archive':archive('quotes',id);break;
case 'project-open':projectModal(id);break;
case 'project-log':logModal(id,true);break;
case 'project-invoice':createInvoice(quote(project(id).quoteId));break;
case 'project-archive':archive('projects',id);break;
case 'invoice-new':{const eligible=state.quotes.filter(q=>q.status==='accepted'&&q.projectId&&!state.invoices.some(i=>i.quoteId===q.id));if(!eligible.length)throw Error('No eligible quotes: accept a quote and create its project first. Existing invoices cannot be duplicated.');openModal('Create invoice from accepted quote',`<div class="form-grid"><label class="full">Accepted quote<select name="quoteId">${eligible.map(q=>`<option value="${q.id}">${esc(q.number+' · '+q.name)} · ${money(totals(q).total)}</option>`).join('')}</select></label></div>`,v=>{closeModal();createInvoice(quote(v.quoteId));},'Create linked invoice');break;}
case 'invoice-open':invoiceModal(id);break;
case 'invoice-payment':paymentModal(id);break;
case 'invoice-queue':{const i=invoice(id);queueMessage('invoice',i.id,i.clientId,'Invoice '+i.number,'Fictional invoice total: '+money(i.total)+'. Due '+i.due+'. No real payment request is sent.');break;}
case 'queue-open':queueModal(id);break;
case 'queue-approve':{const q=state.queue.find(x=>x.id===Number(id));if(q.status!=='awaiting')throw Error('Only items awaiting review can be approved.');q.status='approved';log('Draft explicitly approved; delivery still requires a separate action.',q.clientId,'Approval');closeModal();changed('Approved. Delivery has not been simulated yet.');break;}
case 'queue-reject':{const q=state.queue.find(x=>x.id===Number(id));if(q.status!=='awaiting')throw Error('Only drafts awaiting review can be rejected.');q.status='rejected';closeModal();changed('Draft rejected. Nothing sent.');break;}
case 'queue-deliver':{const q=state.queue.find(x=>x.id===Number(id));if(q.status!=='approved')throw Error('Explicit approval is required before simulated delivery.');q.status='delivered';if(q.type==='quote')quote(q.entityId).status='sent';if(q.type==='invoice'){const i=invoice(q.entityId);if(i.status==='draft')i.status='sent';}log('Simulated delivery: '+q.subject+'. No real email sent.',q.clientId,'Communication');closeModal();changed('Delivery simulated. No email was sent.');break;}
case 'lead-open':leadModal(id);break;
case 'content-new':contentModal();break;
case 'content-open':contentModal(id);break;
case 'content-archive':archive('content',id);break;
default:if(action.startsWith('restore-')){const key=action.slice(8);if(!['inquiries','quotes','projects','content'].includes(key))return;const r=state[key].find(x=>x.id===Number(id));r.archived=false;log('Archived record restored.',r.clientId||null,'Archive');changed('Record restored to its active section.');}
}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){go(nav.dataset.view);return;}const el=e.target.closest('[data-action]');if(!el)return;try{act(el.dataset.action,el.dataset.id);}catch(err){if(dialog.open)$('#form-error').textContent=err.message;else notify(err.message);}});
$('#record-form').addEventListener('submit',e=>{e.preventDefault();if(!modalSave)return;try{modalSave(formValues());}catch(err){$('#form-error').textContent=err.message;}});
dialog.addEventListener('close',()=>{if(!dialog.open){modalSave=null;activeQuote=null;}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const start=e.target.selectionStart;search=e.target.value;$('#view').innerHTML=views[view]();const input=$('#search');input.focus();input.setSelectionRange(start,start);}if(dialog.open&&($('#quote-items')?.contains(e.target)||['tax','discount','deposit'].includes(e.target.name))){try{$('#quote-live-totals').innerHTML=totalMarkup(readQuoteEditor());}catch{/* Invalid fields are handled on save. */}}});
document.addEventListener('change',e=>{if(e.target.id==='status-filter'){filter=e.target.value;$('#view').innerHTML=views[view]();}});
$('#tour-button').addEventListener('click',()=>{tour=0;go('overview');});
$('#reset-button').addEventListener('click',resetModal);
render();
})();
